"""ARMS SearchTracesByPage + GetTrace，拓扑从实际返回的 Span 父子关系产生。"""

import json
import math
from datetime import UTC, datetime
from urllib.parse import urlsplit

import httpx2 as httpx
from pydantic import BaseModel, ConfigDict, Field, ValidationError

from app.connectors.models import ReaderCredentials
from app.connectors.observability.base import ARMSConnector, ObservabilityResponseError
from app.connectors.observability.config import ARMSConfig
from app.connectors.observability.http import (
    ReaderHTTP,
    arms_headers,
    json_response,
    object_response,
    reader_key,
)
from app.connectors.observability.models import Span, TraceRecord, Window


class _Summary(BaseModel):
    model_config = ConfigDict(strict=True, extra="ignore")
    TraceID: str = Field(min_length=1)
    ServiceName: str
    Timestamp: int
    Duration: float = Field(ge=0, allow_inf_nan=False)


class _Page(BaseModel):
    model_config = ConfigDict(strict=True, extra="ignore")
    PageNumber: int = Field(ge=1)
    PageSize: int = Field(ge=1)
    Total: int = Field(ge=0)
    TraceInfos: tuple[_Summary, ...]


class HTTPARMSConnector(ARMSConnector):
    def __init__(
        self,
        config: ARMSConfig,
        credentials: ReaderCredentials,
        *,
        transport: httpx.MockTransport | None = None,
    ) -> None:
        super().__init__(credentials)
        assert self.reader_credentials is not None
        if self.reader_credentials.connector != "arms":
            raise ValueError("ARMS 只接受 arms Reader 凭证")
        self._config = ARMSConfig.model_validate(config)
        self._key = reader_key(self.reader_credentials)
        self._http = ReaderHTTP(self._config, transport)

    async def aclose(self) -> None:
        await self._http.client.aclose()

    async def _call(self, action: str, params: dict[str, str]) -> dict[str, object]:
        params = {"RegionId": self._config.region_id, **params}
        host = urlsplit(self._config.base_url).netloc
        response = await self._http.read("/", params, arms_headers(self._key, host, action, params))
        data = object_response(json_response(response))
        if "Code" in data:
            raise ObservabilityResponseError("ARMS 返回业务错误")
        return data

    async def _spans(self, trace_id: str, params: dict[str, str]) -> tuple[Span, ...]:
        spans: dict[str, Span] = {}
        for page in range(1, self._config.max_pages + 1):
            data = await self._call(
                "GetTrace",
                {
                    **params,
                    "TraceID": trace_id,
                    "PageNumber": str(page),
                    "PageSize": str(self._config.page_size),
                },
            )
            raw = data.get("Spans")
            # Application Monitoring 返回数组，XTrace 返回 {Span: [...]}。
            if isinstance(raw, dict):
                raw = raw.get("Span")
            if not isinstance(raw, list) or len(raw) > self._config.page_size:
                raise ObservabilityResponseError("ARMS Span 列表协议不符")

            def collect(
                values: list[object],
                depth: int = 0,
                previous: frozenset[str] = frozenset(spans),
            ) -> None:
                if depth > 64:
                    raise ValueError("Span 嵌套超过上限")
                for value in values:
                    if isinstance(value, list):
                        collect(value, depth + 1)
                        continue
                    item = object_response(value)
                    unit = 1000 if self._config.span_timestamp_unit == "milliseconds" else 1000000
                    timestamp = item["Timestamp"]
                    duration = item["Duration"]
                    if type(timestamp) is not int or type(duration) not in {float, int}:
                        raise ValueError("Span 时间/耗时类型无效")
                    span = Span.model_validate(
                        {
                            "trace_id": item["TraceID"],
                            "span_id": item["SpanId"],
                            "parent_span_id": item.get("ParentSpanId") or None,
                            "service_name": item["ServiceName"],
                            "timestamp": datetime.fromtimestamp(timestamp / unit, UTC),
                            "duration_ms": duration,
                            "operation": item["OperationName"],
                            "result_code": item["ResultCode"],
                        }
                    )
                    if span.trace_id != trace_id or span.span_id in previous:
                        raise ValueError("Span Trace ID 错配或跨页重复")
                    existing = spans.get(span.span_id)
                    if existing is not None and existing != span:
                        raise ValueError("Span 内容冲突")
                    spans[span.span_id] = span
                    children = item.get("Children", [])
                    if not isinstance(children, list):
                        raise ValueError("Span Children 不是数组")
                    collect(children, depth + 1)

            try:
                collect(raw)
            except (ValueError, ValidationError, KeyError, OverflowError, OSError):
                raise ObservabilityResponseError("ARMS Span 响应协议不符") from None
            if len(raw) < self._config.page_size:
                return tuple(spans.values())
        raise ObservabilityResponseError("ARMS Span 超出分页上限，结果不完整")

    async def query_traces(self, query: Window) -> tuple[TraceRecord, ...]:
        query = Window.model_validate(query)
        # 以整数毫秒覆盖请求时间窗，再在本地按精确 UTC 边界裁剪。
        params = {
            "StartTime": str(math.floor(query.start.timestamp() * 1000)),
            "EndTime": str(math.ceil(query.end.timestamp() * 1000)),
        }
        summaries: list[_Summary] = []
        total: int | None = None
        seen: set[str] = set()
        for index in range(1, self._config.max_pages + 1):
            data = await self._call(
                "SearchTracesByPage",
                {
                    **params,
                    "ServiceName": query.service_name,
                    "PageNumber": str(index),
                    "PageSize": str(self._config.page_size),
                    "Reverse": "false",
                },
            )
            try:
                page = _Page.model_validate_json(json.dumps(data["PageBean"]))
                if (
                    page.PageNumber != index
                    or page.PageSize != self._config.page_size
                    or len(page.TraceInfos) > page.PageSize
                ):
                    raise ValueError("Trace 页号/数量不一致")
                if total is None:
                    total = page.Total
                elif total != page.Total:
                    raise ValueError("Trace 查询分页期间总数变化")
                for summary in page.TraceInfos:
                    if summary.ServiceName != query.service_name or summary.TraceID in seen:
                        raise ValueError("Trace 服务不符或 ID 重复")
                    seen.add(summary.TraceID)
                    summaries.append(summary)
                if len(summaries) > total or (not page.TraceInfos and len(summaries) < total):
                    raise ValueError("Trace 分页不完整")
            except (ValueError, ValidationError, KeyError):
                raise ObservabilityResponseError("ARMS Trace 响应协议不符") from None
            if len(summaries) == total:
                break
        else:
            raise ObservabilityResponseError("ARMS Trace 超出分页上限，结果不完整")
        result: list[TraceRecord] = []
        for summary in summaries:
            try:
                timestamp = datetime.fromtimestamp(summary.Timestamp / 1000, UTC)
            except (ValueError, OverflowError, OSError):
                raise ObservabilityResponseError("ARMS Trace 时间无效") from None
            if not query.contains(timestamp):
                continue
            spans = await self._spans(summary.TraceID, params)
            result.append(
                TraceRecord(
                    trace_id=summary.TraceID,
                    service_name=query.service_name,
                    timestamp=timestamp,
                    duration_ms=summary.Duration,
                    source_ref=f"arms:{summary.TraceID}",
                    spans=tuple(
                        sorted(
                            (s for s in spans if query.contains(s.timestamp)),
                            key=lambda s: (s.timestamp, s.span_id),
                        )
                    ),
                )
            )
        return tuple(sorted(result, key=lambda trace: (trace.timestamp, trace.trace_id)))

"""三个同构的只读接口；查询不包含端点或身份参数。"""

from abc import abstractmethod

from app.connectors.base import ReadOnlyConnector
from app.connectors.observability.models import (
    LogRecord,
    MetricSeries,
    MetricsQuery,
    TraceRecord,
    Window,
)


class ObservabilityError(RuntimeError):
    pass


class ObservabilityResponseError(ObservabilityError):
    pass


class ObservabilityHTTPError(ObservabilityError):
    def __init__(self, status_code: int) -> None:
        self.status_code = status_code
        super().__init__(f"可观测性读取失败（HTTP {status_code}）")


class ObservabilityTimeout(ObservabilityError):
    pass


class PrometheusConnector(ReadOnlyConnector):
    @abstractmethod
    async def query_metrics(self, query: MetricsQuery) -> tuple[MetricSeries, ...]: ...


class SLSConnector(ReadOnlyConnector):
    @abstractmethod
    async def query_logs(self, query: Window) -> tuple[LogRecord, ...]: ...


class ARMSConnector(ReadOnlyConnector):
    @abstractmethod
    async def query_traces(self, query: Window) -> tuple[TraceRecord, ...]: ...

"""显式端点/字段映射来自环境变量；Alibaba 凭证保存在 Reader 的 SecretStr 中。"""

from typing import Annotated, Literal
from urllib.parse import urlsplit

from pydantic import BaseModel, ConfigDict, Field, SecretStr, field_validator

FieldName = Annotated[str, Field(pattern=r"^[A-Za-z_][A-Za-z0-9_]{0,127}$")]


class EndpointConfig(BaseModel):
    model_config = ConfigDict(
        frozen=True, extra="forbid", revalidate_instances="always", hide_input_in_errors=True
    )
    base_url: str
    timeout_seconds: float = Field(default=15, gt=0, le=120, allow_inf_nan=False)
    page_size: int = Field(default=100, ge=1, le=100)
    max_pages: int = Field(default=100, ge=1, le=1000)

    @field_validator("base_url")
    @classmethod
    def url(cls, value: str) -> str:
        try:
            parsed = urlsplit(value)
            valid = (
                parsed.scheme == "https"
                and bool(parsed.hostname)
                and parsed.port != 0
                and parsed.username is None
                and parsed.password is None
                and not parsed.query
                and not parsed.fragment
                and "\\" not in value
                and not any(char.isspace() or ord(char) < 32 for char in value)
                and all(part not in {".", ".."} for part in parsed.path.split("/"))
                and "%" not in parsed.path
            )
        except ValueError:
            valid = False
        if not valid:
            raise ValueError("可观测性 base_url 必须是无凭证的 HTTPS 地址")
        return value.rstrip("/") + "/"


class PrometheusConfig(EndpointConfig):
    service_label: FieldName = "service"
    max_series: int = Field(default=1000, ge=1, le=10000)


class SLSConfig(EndpointConfig):
    project: str = Field(pattern=r"^[a-z0-9][a-z0-9-]{0,127}$")
    logstore: str = Field(pattern=r"^[a-z0-9][a-z0-9_-]{0,127}$")
    service_field: FieldName = "service_name"
    level_field: FieldName = "level"
    message_field: FieldName = "message"

    @field_validator("base_url")
    @classmethod
    def root_url(cls, value: str) -> str:
        if urlsplit(value).path != "/":
            raise ValueError("SLS base_url 必须是 project 端点且无路径")
        return value


class ARMSConfig(EndpointConfig):
    region_id: str = Field(pattern=r"^[a-z0-9][a-z0-9-]{0,63}$")
    # ARMS Application Monitoring 与 XTrace 版本的时间单位不同，必须显式选定。
    span_timestamp_unit: Literal["milliseconds", "microseconds"] = "milliseconds"

    @field_validator("base_url")
    @classmethod
    def root_url(cls, value: str) -> str:
        if urlsplit(value).path != "/":
            raise ValueError("ARMS base_url 必须是无路径的 API 端点")
        return value


class AlibabaReaderKey(BaseModel):
    model_config = ConfigDict(frozen=True, extra="forbid", hide_input_in_errors=True)
    access_key_id: SecretStr
    access_key_secret: SecretStr
    security_token: SecretStr | None = None

    @field_validator("access_key_id", "access_key_secret", "security_token")
    @classmethod
    def nonempty(cls, value: SecretStr | None) -> SecretStr | None:
        if value is not None and (
            not value.get_secret_value()
            or any(char.isspace() or ord(char) < 32 for char in value.get_secret_value())
        ):
            raise ValueError("Alibaba Reader 凭证不能为空或包含空白/控制字符")
        return value

"""Step 23 可脚本化样例；仅测试/演示显式注入，不替换默认 Fake 数据。"""

from datetime import timedelta

from app.connectors.observability.fake import FakePrometheusConnector
from app.connectors.observability.models import MetricPoint, MetricSeries, MetricsQuery


class FakeDetectionPrometheusConnector(FakePrometheusConnector):
    def __init__(self, *, healthy: bool = False) -> None:
        super().__init__(())
        self.healthy = healthy

    async def query_metrics(self, query: MetricsQuery) -> tuple[MetricSeries, ...]:
        query = MetricsQuery.model_validate(query)
        self._check()
        values = {
            "disk_used_ratio": (0.5, 0.02),
            "http_requests_rate": (100.0, 10.0),
            "daily_cost": (100.0, 10.0),
            "cpu_usage_ratio": (0.4, 0.035),
        }
        if query.metric_name not in values:
            return ()
        base, growth = values[query.metric_name]
        count = int((query.end - query.start).total_seconds() / query.step_seconds)
        return (
            MetricSeries(
                service_name=query.service_name,
                metric_name=query.metric_name,
                labels={"service": query.service_name, "resource": "fake-resource"},
                points=tuple(
                    MetricPoint(
                        timestamp=query.start + timedelta(seconds=i * query.step_seconds),
                        value=base if self.healthy else base + growth * i,
                    )
                    for i in range(count)
                ),
            ),
        )

"""复用 ConnectorFactory；默认 Fake，local/test 不能创建真实客户端。"""

import httpx2 as httpx

from app.config import Settings
from app.connectors.factory import ConnectorFactory
from app.connectors.models import ReaderCredentials
from app.connectors.observability.arms import HTTPARMSConnector
from app.connectors.observability.base import ARMSConnector, PrometheusConnector, SLSConnector
from app.connectors.observability.fake import (
    FakeARMSConnector,
    FakePrometheusConnector,
    FakeSLSConnector,
)
from app.connectors.observability.prometheus import HTTPPrometheusConnector
from app.connectors.observability.reviewer_fake import reviewer_traces
from app.connectors.observability.sls import HTTPSLSConnector


def create_prometheus_connector(
    settings: Settings, *, transport: httpx.MockTransport | None = None
) -> PrometheusConnector:
    def real(credentials: ReaderCredentials) -> PrometheusConnector:
        return HTTPPrometheusConnector(
            settings.require_prometheus_config(), credentials, transport=transport
        )

    return ConnectorFactory[PrometheusConnector](
        "prometheus", fake=FakePrometheusConnector, real=real
    ).create(settings)


def create_sls_connector(
    settings: Settings, *, transport: httpx.MockTransport | None = None
) -> SLSConnector:
    def real(credentials: ReaderCredentials) -> SLSConnector:
        return HTTPSLSConnector(settings.require_sls_config(), credentials, transport=transport)

    return ConnectorFactory[SLSConnector]("sls", fake=FakeSLSConnector, real=real).create(settings)


def create_arms_connector(
    settings: Settings, *, transport: httpx.MockTransport | None = None, reviewer: bool = False
) -> ARMSConnector:
    def real(credentials: ReaderCredentials) -> ARMSConnector:
        return HTTPARMSConnector(settings.require_arms_config(), credentials, transport=transport)

    return ConnectorFactory[ARMSConnector](
        "arms",
        fake=lambda: FakeARMSConnector(reviewer_traces()) if reviewer else FakeARMSConnector(),
        real=real,
    ).create(settings)

"""可注入的离线快照；默认数据包括边界外和其他服务记录以验证筛选。"""

from datetime import UTC, datetime, timedelta

from pydantic import TypeAdapter

from app.connectors.base import ReadOnlyConnector
from app.connectors.observability.base import (
    ARMSConnector,
    ObservabilityError,
    PrometheusConnector,
    SLSConnector,
)
from app.connectors.observability.models import (
    LogRecord,
    MetricPoint,
    MetricSeries,
    MetricsQuery,
    Span,
    TraceRecord,
    Window,
)

SAMPLE_START = datetime(2026, 10, 1, 1, tzinfo=UTC)
SAMPLE_END = SAMPLE_START + timedelta(minutes=10)


def discovery_traces(end: datetime) -> tuple[TraceRecord, ...]:
    """Step 18 专用样例：时间相对查询窗口移动，显式包含上下游父子 Span。"""
    timestamp = end - timedelta(seconds=30)
    trace_id = "discovery-payment-sample"
    return (
        TraceRecord(
            trace_id=trace_id,
            service_name="payment-service",
            timestamp=timestamp,
            duration_ms=1500.0,
            source_ref="arms:discovery-sample",
            spans=tuple(
                Span(
                    trace_id=trace_id,
                    span_id=span_id,
                    parent_span_id=parent,
                    service_name=service,
                    timestamp=timestamp,
                    duration_ms=1000.0,
                    operation="Discovery 样例调用",
                    result_code="ok",
                )
                for span_id, parent, service in (
                    ("checkout", None, "checkout-service"),
                    ("payment", "checkout", "payment-service"),
                    ("db", "payment", "payment-db"),
                )
            ),
        ),
    )


def sample_metrics() -> tuple[MetricSeries, ...]:
    return tuple(
        MetricSeries(
            service_name=service,
            metric_name="http_5xx_ratio",
            labels={"__name__": "http_5xx_ratio", "service": service},
            points=tuple(
                MetricPoint(timestamp=SAMPLE_START + timedelta(minutes=minute), value=value)
                for minute, value in [(-1, 0.01), (0, 0.02), (5, 0.12), (10, 0.03), (11, 0.01)]
            ),
        )
        for service in ("payment-service", "checkout-service")
    )


def sample_logs() -> tuple[LogRecord, ...]:
    return tuple(
        LogRecord(
            service_name=service,
            timestamp=SAMPLE_START + timedelta(minutes=minute),
            level="ERROR",
            message="样例：数据库连接池等待超时",
            source_ref="sls:fake/payment-logs",
        )
        for service in ("payment-service", "checkout-service")
        for minute in (-1, 0, 5, 10, 11)
    )


def sample_traces() -> tuple[TraceRecord, ...]:
    traces: list[TraceRecord] = []
    for service in ("payment-service", "checkout-service"):
        for minute in (-1, 0, 5, 10, 11):
            timestamp = SAMPLE_START + timedelta(minutes=minute)
            trace_id = f"trace-{service}-{minute}"
            root = Span(
                trace_id=trace_id,
                span_id="root",
                service_name=service,
                timestamp=timestamp,
                duration_ms=1500.0,
                operation="POST /pay",
                result_code="500",
            )
            child = Span(
                trace_id=trace_id,
                span_id="db",
                parent_span_id="root",
                service_name="payment-db",
                timestamp=timestamp + timedelta(seconds=1),
                duration_ms=1400.0,
                operation="获取数据库连接",
                result_code="timeout",
            )
            traces.append(
                TraceRecord(
                    trace_id=trace_id,
                    service_name=service,
                    timestamp=timestamp,
                    duration_ms=1500.0,
                    spans=(root, child),
                    source_ref=f"arms:{trace_id}",
                )
            )
    return tuple(traces)


class _FakeReader(ReadOnlyConnector):
    def __init__(self) -> None:
        super().__init__()
        self._closed = False

    async def aclose(self) -> None:
        self._closed = True

    def _check(self) -> None:
        if self._closed:
            raise ObservabilityError("可观测性 Connector 已关闭")


class FakePrometheusConnector(_FakeReader, PrometheusConnector):
    def __init__(self, series: tuple[MetricSeries, ...] | None = None) -> None:
        super().__init__()
        self._series = tuple(
            item.model_copy(deep=True)
            for item in TypeAdapter(tuple[MetricSeries, ...]).validate_python(
                series if series is not None else sample_metrics(), strict=True
            )
        )

    async def query_metrics(self, query: MetricsQuery) -> tuple[MetricSeries, ...]:
        query = MetricsQuery.model_validate(query)
        self._check()
        result: list[MetricSeries] = []
        for series in self._series:
            if series.service_name != query.service_name or series.metric_name != query.metric_name:
                continue
            # Fake 只保留查询采样网格上的已注入点，不合成不存在的观测。
            points = tuple(
                sorted(
                    (
                        point
                        for point in series.points
                        if query.contains(point.timestamp)
                        and (point.timestamp - query.start).total_seconds() % query.step_seconds
                        == 0
                    ),
                    key=lambda point: point.timestamp,
                )
            )
            if points:
                result.append(
                    MetricSeries(
                        service_name=series.service_name,
                        metric_name=series.metric_name,
                        labels=dict(series.labels),
                        points=points,
                    ).model_copy(deep=True)
                )
        return tuple(result)


class FakeSLSConnector(_FakeReader, SLSConnector):
    def __init__(self, logs: tuple[LogRecord, ...] | None = None) -> None:
        super().__init__()
        self._logs = tuple(
            item.model_copy(deep=True)
            for item in TypeAdapter(tuple[LogRecord, ...]).validate_python(
                logs if logs is not None else sample_logs(), strict=True
            )
        )

    async def query_logs(self, query: Window) -> tuple[LogRecord, ...]:
        query = Window.model_validate(query)
        self._check()
        return tuple(
            item.model_copy(deep=True)
            for item in sorted(
                (
                    log
                    for log in self._logs
                    if log.service_name == query.service_name and query.contains(log.timestamp)
                ),
                key=lambda log: log.timestamp,
            )
        )


class FakeARMSConnector(_FakeReader, ARMSConnector):
    def __init__(self, traces: tuple[TraceRecord, ...] | None = None) -> None:
        super().__init__()
        self._traces = tuple(
            item.model_copy(deep=True)
            for item in TypeAdapter(tuple[TraceRecord, ...]).validate_python(
                traces if traces is not None else sample_traces(), strict=True
            )
        )

    async def query_traces(self, query: Window) -> tuple[TraceRecord, ...]:
        query = Window.model_validate(query)
        self._check()
        return tuple(
            TraceRecord(
                trace_id=trace.trace_id,
                service_name=trace.service_name,
                timestamp=trace.timestamp,
                duration_ms=trace.duration_ms,
                source_ref=trace.source_ref,
                spans=tuple(
                    span.model_copy(deep=True)
                    for span in trace.spans
                    if query.contains(span.timestamp)
                ),
            )
            for trace in sorted(self._traces, key=lambda t: (t.timestamp, t.trace_id))
            if trace.service_name == query.service_name and query.contains(trace.timestamp)
        )

"""仅供本包固定 GET 接口使用，签名不向 Tool 暴露；不自建重试。"""

import base64
import hashlib
import hmac
from datetime import UTC, datetime
from email.utils import format_datetime
from urllib.parse import quote
from uuid import uuid4

import httpx2 as httpx
from pydantic import ValidationError

from app.connectors.models import ReaderCredentials
from app.connectors.observability.base import (
    ObservabilityError,
    ObservabilityHTTPError,
    ObservabilityResponseError,
    ObservabilityTimeout,
)
from app.connectors.observability.config import AlibabaReaderKey, EndpointConfig


class ReaderHTTP:
    def __init__(self, config: EndpointConfig, transport: httpx.MockTransport | None) -> None:
        if transport is not None and not isinstance(transport, httpx.MockTransport):
            raise TypeError("测试 transport 只接受 MockTransport")
        self.client = httpx.AsyncClient(
            base_url=config.base_url,
            timeout=config.timeout_seconds,
            transport=transport,
            trust_env=False,
            follow_redirects=False,
            headers={"Accept": "application/json"},
        )

    async def read(
        self, path: str, params: dict[str, str], headers: dict[str, str]
    ) -> httpx.Response:
        if self.client.is_closed:
            raise ObservabilityError("可观测性 Connector 已关闭")
        try:
            response = await self.client.get(path, params=params, headers=headers)
        except httpx.TimeoutException:
            raise ObservabilityTimeout("可观测性读取超时") from None
        except httpx.RequestError:
            raise ObservabilityError("可观测性连接失败") from None
        if response.status_code != 200:
            raise ObservabilityHTTPError(response.status_code)
        return response


def reader_key(credentials: ReaderCredentials) -> AlibabaReaderKey:
    try:
        return AlibabaReaderKey.model_validate_json(credentials.token.get_secret_value())
    except (ValueError, ValidationError):
        raise ValueError("SLS/ARMS Reader token 必须是包含 AccessKey 的凭证 JSON") from None


def sls_headers(key: AlibabaReaderKey, path: str, params: dict[str, str]) -> dict[str, str]:
    headers = {
        "x-log-apiversion": "0.6.0",
        "x-log-signaturemethod": "hmac-sha1",
        "x-log-bodyrawsize": "0",
        "Date": format_datetime(datetime.now(UTC), usegmt=True),
    }
    if key.security_token is not None:
        headers["x-acs-security-token"] = key.security_token.get_secret_value()
    canonical_headers = "".join(
        f"{name}:{value}\n" for name, value in sorted(headers.items()) if name.startswith("x-")
    )
    resource = path + "?" + "&".join(f"{k}={v}" for k, v in sorted(params.items()))
    message = "GET\n\n\n" + headers["Date"] + "\n" + canonical_headers + resource
    signature = base64.b64encode(
        hmac.digest(key.access_key_secret.get_secret_value().encode(), message.encode(), "sha1")
    ).decode()
    headers["Authorization"] = f"LOG {key.access_key_id.get_secret_value()}:{signature}"
    return headers


def arms_headers(
    key: AlibabaReaderKey, host: str, action: str, params: dict[str, str]
) -> dict[str, str]:
    headers = {
        "host": host,
        "x-acs-action": action,
        "x-acs-version": "2019-08-08",
        "x-acs-date": datetime.now(UTC).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "x-acs-signature-nonce": uuid4().hex,
        "x-acs-content-sha256": hashlib.sha256(b"").hexdigest(),
    }
    if key.security_token is not None:
        headers["x-acs-security-token"] = key.security_token.get_secret_value()
    signed = ";".join(sorted(headers))
    canonical_headers = "".join(f"{k}:{v.strip()}\n" for k, v in sorted(headers.items()))
    canonical_query = "&".join(
        f"{quote(k, safe='~')}={quote(v, safe='~')}" for k, v in sorted(params.items())
    )
    canonical = "\n".join(
        [
            "GET",
            "/",
            canonical_query,
            canonical_headers,
            signed,
            headers["x-acs-content-sha256"],
        ]
    )
    message = "ACS3-HMAC-SHA256\n" + hashlib.sha256(canonical.encode()).hexdigest()
    signature = hmac.new(
        key.access_key_secret.get_secret_value().encode(), message.encode(), hashlib.sha256
    ).hexdigest()
    headers["Authorization"] = (
        f"ACS3-HMAC-SHA256 Credential={key.access_key_id.get_secret_value()},"
        f"SignedHeaders={signed},Signature={signature}"
    )
    return headers


def json_response(response: httpx.Response) -> object:
    try:
        return response.json()
    except ValueError:
        raise ObservabilityResponseError("可观测性响应不是 JSON") from None


def object_response(value: object) -> dict[str, object]:
    if not isinstance(value, dict) or any(not isinstance(key, str) for key in value):
        raise ObservabilityResponseError("可观测性响应必须是 JSON 对象")
    return value

"""按需查询的最小快照，统一使用 UTC 半开时间窗 [start, end)。"""

from datetime import UTC, datetime, timedelta
from typing import Annotated, Literal

from pydantic import AwareDatetime, BaseModel, ConfigDict, Field, field_validator, model_validator

ServiceName = Annotated[str, Field(pattern=r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$")]
MetricName = Annotated[str, Field(pattern=r"^[a-zA-Z_:][a-zA-Z0-9_:]{0,127}$")]
Identifier = Annotated[str, Field(min_length=1, max_length=256, pattern=r"^\S+$")]


class Snapshot(BaseModel):
    model_config = ConfigDict(
        strict=True,
        frozen=True,
        extra="forbid",
        revalidate_instances="always",
        hide_input_in_errors=True,
    )


class Window(Snapshot):
    service_name: ServiceName
    start: AwareDatetime
    end: AwareDatetime

    @field_validator("start", "end")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)

    @model_validator(mode="after")
    def ordered(self) -> "Window":
        if not timedelta(0) < self.end - self.start <= timedelta(days=1):
            raise ValueError("时间窗必须 start < end 且不超过 24 小时")
        return self

    def contains(self, timestamp: datetime) -> bool:
        return self.start <= timestamp < self.end


class MetricsQuery(Window):
    metric_name: MetricName = "http_5xx_ratio"
    step_seconds: int = Field(default=60, ge=1, le=3600)

    @model_validator(mode="after")
    def bounded_samples(self) -> "MetricsQuery":
        if (self.end - self.start).total_seconds() / self.step_seconds > 11000:
            raise ValueError("单条序列的采样点不能超过 11000")
        return self


class MetricPoint(Snapshot):
    timestamp: AwareDatetime
    value: float = Field(allow_inf_nan=False)

    @field_validator("timestamp")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)


class MetricSeries(Snapshot):
    service_name: ServiceName
    metric_name: MetricName
    labels: dict[str, str]
    points: tuple[MetricPoint, ...]


class LogRecord(Snapshot):
    service_name: ServiceName
    timestamp: AwareDatetime
    level: str = Field(min_length=1, max_length=32)
    message: str = Field(max_length=100_000)
    source_ref: str = Field(min_length=1)

    @field_validator("timestamp")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)


class Span(Snapshot):
    trace_id: Identifier
    span_id: Identifier
    parent_span_id: str | None = Field(default=None, max_length=256)
    service_name: ServiceName
    timestamp: AwareDatetime
    duration_ms: float = Field(ge=0, allow_inf_nan=False)
    operation: str = Field(min_length=1, max_length=2048)
    result_code: str = Field(max_length=64)

    @field_validator("timestamp")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)


class TraceRecord(Snapshot):
    trace_id: Identifier
    service_name: ServiceName
    timestamp: AwareDatetime
    duration_ms: float = Field(ge=0, allow_inf_nan=False)
    spans: tuple[Span, ...]
    source_ref: str = Field(min_length=1)

    @field_validator("timestamp")
    @classmethod
    def utc(cls, value: datetime) -> datetime:
        return value.astimezone(UTC)

    @model_validator(mode="after")
    def span_ids(self) -> "TraceRecord":
        if len({span.span_id for span in self.spans}) != len(self.spans):
            raise ValueError("同一 Trace 中 Span ID 不能重复")
        if any(span.trace_id != self.trace_id for span in self.spans):
            raise ValueError("Span 必须属于当前 Trace")
        return self


class TopologyEdge(Snapshot):
    trace_id: Identifier
    parent_span_id: Identifier
    span_id: Identifier
    source_service: ServiceName
    target_service: ServiceName
    source: Literal["arms"] = "arms"


def topology(traces: tuple[TraceRecord, ...]) -> tuple[TopologyEdge, ...]:
    """仅从返回的 Span 父子关系取样，不推断缺失关系或更新 Context Graph。"""
    edges: list[TopologyEdge] = []
    for trace in traces:
        by_id = {span.span_id: span for span in trace.spans}
        for span in trace.spans:
            parent = by_id.get(span.parent_span_id or "")
            if parent is not None and parent.span_id != span.span_id:
                edges.append(
                    TopologyEdge(
                        trace_id=trace.trace_id,
                        parent_span_id=parent.span_id,
                        span_id=span.span_id,
                        source_service=parent.service_name,
                        target_service=span.service_name,
                    )
                )
    return tuple(edges)

