                    f.model_copy(update={"value": False})
                    if abnormal
                    and f.check_id in {"service_health", "alerts_healthy", "logs_healthy"}
                    else f
                    for f in facts.facts
                )
            }
        )
        return WarRoomFacts(
            query=value,
            inspection=facts,
            per_replica_rps=250.0,
            current_rps=1000.0 if value.purpose == "watch" else 400.0,
            rollback_ready=True,
